def superPow(a, b):
    MOD = 1337

    def pw(x, k):
        r = 1
        while k:
            if k & 1:
                r = r * x % MOD
            x = x * x % MOD
            k >>= 1
        return r

    a %= MOD
    result = 1
    for d in b:
        result = pw(result, 10) * pw(a, d) % MOD
    return result
